NEWF = json.loads(r'''{"inc/walkin-next.php": "<?php\ndeclare(strict_types=1);\n// (2.99.607 - LENH 604) \"You're next\" text for walk-ins: the customer checked in on the iPad, went to wait in the car;\n// when they are first in line for a tech who will be free within 10 minutes -> ONE text. One per visit, never again.\n// Not texted: they got their turn right at check-in (still inside), the kiosk tick was off, the Settings switch is off,\n// STOP / wrong numbers, appointments (only walk-ins). Turn rules are only READ here (ta_state) - nothing in the turn line changes.\n// States: appt_log 'yn_opt' (kiosk tick on/off + language), 'yn_sent' (the time) - the rest (seen waiting / skipped) in setting yn_day.\n\nconst YN_MIN = 10; // a tech free within this many minutes = \"you're next\"\n\nfunction yn_on(): bool { return (string)setting('walkin_next_text') !== '0'; }\n\n/** setting yn_day = {\"d\":\"Y-m-d\",\"a\":{\"<appt id>\":\"w\"|\"n\"}} - read fresh from the database (the kiosk and the cron both write it). */\nfunction yn_day(): array {\n    $v = (string)(q(\"SELECT v FROM settings WHERE k = 'yn_day'\")->fetchColumn() ?: '');\n    $j = json_decode($v, true); $d = date('Y-m-d');\n    return is_array($j) && ($j['d'] ?? '') === $d && is_array($j['a'] ?? null) ? $j : ['d' => $d, 'a' => []];\n}\nfunction yn_mark(int $id, string $v): void {\n    $j = yn_day(); $j['a'][(string)$id] = $v; set_setting('yn_day', json_encode($j));\n}\n\n/** appt id => ['opt' => 'on'|'off'|'', 'es' => bool, 'sent' => 'g:i'|''] from the appointment's own log lines. */\nfunction yn_flags(array $ids): array {\n    $out = []; foreach ($ids as $i) $out[(int)$i] = ['opt' => '', 'es' => false, 'sent' => ''];\n    if (!$ids) return $out;\n    foreach (q(\"SELECT appt_id, action, detail FROM appt_log WHERE action IN ('yn_opt', 'yn_sent') AND appt_id IN (\" . implode(',', array_map('intval', $ids)) . ') ORDER BY id')->fetchAll() as $r) {\n        $i = (int)$r['appt_id']; $d = (string)$r['detail'];\n        if ($r['action'] === 'yn_sent') $out[$i]['sent'] = preg_match('/(\\d{1,2}:\\d\\d)/', $d, $m) ? $m[1] : '?';\n        else { $out[$i]['opt'] = str_contains($d, ': off') ? 'off' : 'on'; $out[$i]['es'] = str_contains($d, 'Espa'); }\n    }\n    return $out;\n}\n\n/** For the Check-in list: appt id => \"10:42\" (texted \"You're next\" at). */\nfunction yn_map(string $date): array {\n    $out = [];\n    try { foreach (q(\"SELECT l.appt_id, l.detail FROM appt_log l JOIN appointments a ON a.id = l.appt_id WHERE a.appt_date = ? AND l.action = 'yn_sent'\", [$date])->fetchAll() as $r)\n        $out[(int)$r['appt_id']] = preg_match('/(\\d{1,2}:\\d\\d)/', (string)$r['detail'], $m) ? $m[1] : ''; } catch (Throwable $e) {}\n    return $out;\n}\n\n/** Today's waiting customers (arrived, not started), in the order they came. */\nfunction yn_waiting(string $date): array {\n    return q(\"SELECT * FROM appointments WHERE appt_date = ? AND kind = 'appt' AND status = 'arrived' AND started_at = '' AND done_at = '' AND arrived_at <> '' ORDER BY arrived_at, id\", [$date])->fetchAll();\n}\n\n/** appt id => ['staff' => tech, 'min' => minutes until that tech is free] for each waiting customer who is FIRST in line for that tech.\n    Read from the turn state the Check-in screen shows (ta_state); turn line off -> the same \"tech free soonest\" by itself. */\nfunction yn_first(string $date, array $ws): array {\n    if (!function_exists('ta_state')) require_once __DIR__ . '/turnq.php';\n    $auto = ta_on() ? ta_state($date) : yn_plain($date, $ws);\n    $L = null; $breaks = null; $taken = []; $out = [];\n    foreach ($ws as $a) { $id = (int)$a['id']; $e = $auto[$id] ?? null; if (!$e) continue;\n        $k = (string)($e['kind'] ?? ''); $t = (int)($e['staff'] ?? 0); $min = null;\n        if ($k === 'offer') $min = 0;\n        elseif ($k === 'wait') $min = (int)$e['min'];\n        elseif ($k === 'ask') $min = max(0, (int)($e['busy'] ?? 0));\n        elseif ($k === 'hold') $min = (int)ceil(max(0, (int)($e['left'] ?? 0)) / 60);\n        elseif ($k === 'req' && $t) { if ($L === null) { $L = tq_line($date); $breaks = ta_breaks($date); }\n            if (in_array($t, $L['order'], true) && !isset($breaks[$t])) $min = (int)ceil((tech_free_at($t, $date) - time()) / 60); }\n        if ($min === null || !$t) continue;\n        if (isset($taken[$t])) continue; // someone who came earlier waits for the same tech: not next yet\n        $taken[$t] = true; $out[$id] = ['staff' => $t, 'min' => max(0, $min)];\n    }\n    return $out;\n}\n/** The turn line switched off: each customer's tech (asked for by name, or any tech who can do it) and when that tech is free. */\nfunction yn_plain(string $date, array $ws): array {\n    $L = tq_line($date); $breaks = ta_breaks($date); $skills = ta_skills(); $out = [];\n    foreach ($ws as $a) { $sids = ids_list((string)$a['service_ids']);\n        $cand = (int)$a['staff_id'] > 0 && (int)($a['auto_tech'] ?? 0) === 0 ? [(int)$a['staff_id']] : $L['order'];\n        $best = null; foreach ($cand as $sid) { $sid = (int)$sid; if (!in_array($sid, $L['order'], true) || isset($breaks[$sid]) || !ta_can($skills, $sid, $sids)) continue;\n            $f = tech_free_at($sid, $date); if ($best === null || $f < $best[1]) $best = [$sid, $f]; }\n        if ($best) $out[(int)$a['id']] = ['kind' => 'wait', 'staff' => $best[0], 'min' => max(0, (int)ceil(($best[1] - time()) / 60))];\n    }\n    return $out;\n}\n/** One walk-in fits: has a mobile number, and is first in line with a tech free within 10 minutes. */\nfunction yn_fits(array $a, array $first): bool {\n    return (int)($a['walkin'] ?? 0) === 1 && strlen((string)$a['phone']) === 12 && isset($first[(int)$a['id']]) && $first[(int)$a['id']]['min'] <= YN_MIN;\n}\n\n/** The kiosk made a walk-in: remember the tick (+ the language), and whether they got their turn right away (then never texted). */\nfunction yn_checkin(array $a, bool $on, bool $es): void {\n    if ((int)($a['walkin'] ?? 0) !== 1) return;\n    appt_log($a, 'yn_opt', \"Text me when it's my turn: \" . ($on ? 'on' : 'off') . ($es ? ' (Espa\u00f1ol)' : ''));\n    if (!$on || !yn_on()) return;\n    $date = (string)$a['appt_date']; $ws = yn_waiting($date); $first = yn_first($date, $ws);\n    yn_mark((int)$a['id'], yn_fits($a, $first) ? 'n' : 'w');\n}\n\nfunction yn_text(bool $es): string {\n    $s = salon_short();\n    return $es ? $s . ': \u00a1Usted es el siguiente! Por favor regrese en unos 5\u201310 minutos. \u00a1Gracias!'\n        : $s . \": You're next! Please come back inside in about 5\u201310 minutes. Thank you!\";\n}\n\n/** Every minute (cron/turn.php): text the walk-ins who just became next. Returns how many were texted. */\nfunction yn_tick(?string $date = null): int {\n    if (!yn_on()) return 0;\n    $date = $date ?? date('Y-m-d'); if ($date !== date('Y-m-d')) return 0;\n    $ws = yn_waiting($date);\n    $walk = array_values(array_filter($ws, fn($a) => (int)($a['walkin'] ?? 0) === 1 && strlen((string)$a['phone']) === 12));\n    if (!$walk) return 0;\n    $fl = yn_flags(array_map(fn($a) => (int)$a['id'], $walk)); $day = yn_day()['a']; $first = null; $n = 0;\n    // a number already texted today (a party of 2 on one phone, or checked in again): never a 2nd text\n    $texted = []; foreach (q(\"SELECT a.phone FROM appt_log l JOIN appointments a ON a.id = l.appt_id WHERE a.appt_date = ? AND l.action = 'yn_sent'\", [$date])->fetchAll() as $r) $texted[(string)$r['phone']] = true;\n    foreach ($walk as $a) { $id = (int)$a['id']; $f = $fl[$id];\n        if ($f['opt'] === 'off' || $f['sent'] !== '' || ($day[(string)$id] ?? '') === 'n' || isset($texted[(string)$a['phone']])) continue;\n        if ($first === null) $first = yn_first($date, $ws);\n        $fits = yn_fits($a, $first);\n        if (!isset($day[(string)$id])) { yn_mark($id, $fits ? 'n' : 'w'); continue; } // first look: next already (still inside) -> never; else watch\n        if (!$fits) continue;\n        if (!function_exists('as_add')) require_once __DIR__ . '/autosend.php';\n        if (!function_exists('out_lang_es')) require_once __DIR__ . '/outbox.php';\n        $p = (string)$a['phone'];\n        if (!as_ready()) continue; // no texting device (Android / SMS Server) for this salon: nothing to send with - look again next minute\n        if (!out_not_stopped($p) || sms_cant($p)) { yn_mark($id, 'n'); continue; } // STOP / can't text: the existing rules\n        $es = $f['es'] || out_lang_es($a);\n        $aid = as_add('reply', 'ui:ynext:' . $id, $p, (string)$a['customer_name'], yn_text($es), \"Walk-in: you're next\");\n        if (!$aid) { yn_mark($id, 'n'); continue; }\n        as_flush(false, [$aid]);\n        appt_log($a, 'yn_sent', \"\ud83d\udcf1 Texted \\\"You're next\\\" \" . date('g:i')); $texted[$p] = true; $n++;\n    }\n    return $n;\n}\n"}''')
